import {available,defaultSchedule,dateKey,clock,validateSchedule} from './domain.js';
import {animateView,animateStep,closeSheet,icons,updateNavigation,updateProgress,setupMotion} from './motion.js';
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const duration=n=>n%60?`${Math.floor(n/60)?Math.floor(n/60)+' ч ':''}${n%60} мин`:`${n/60} ч`;
const niceDate=d=>new Date(d+'T12:00:00+03:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const statusNames={pending:'Ожидает подтверждения',confirmed:'Подтверждена',completed:'Выполнена',cancelled:'Отменена'};
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const save=(key,value)=>localStorage.setItem(key,JSON.stringify(value));
let config,demo=false,view='home',ownerTab='appointments',ownerData,booking={},step=0,slotGeneration=0,pollTimer;
const demoState=()=>read('graphite-demo',{bookings:[],schedule:defaultSchedule()});
async function api(path,method='GET',data,token){
 const response=await fetch(new URL('api'+path,import.meta.url),{method,headers:{'Content-Type':'application/json',...(token?{'X-Booking-Token':token}:{})},...(data?{body:JSON.stringify(data)}:{})});
 let result;try{result=await response.json();}catch{throw new Error('Сервер вернул некорректный ответ');}if(!response.ok)throw new Error(result.error||'Не удалось выполнить запрос');return result;
}
const toast=message=>{$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);};
const info=(title,content)=>{$('#info-title').textContent=title;$('#info-content').innerHTML=content;$('#info-dialog').showModal();};
$('#info-close').onclick=()=>closeSheet($('#info-dialog'));$('#booking-close').onclick=()=>closeSheet($('#booking-dialog'));
for(const d of document.querySelectorAll('dialog')){d.addEventListener('cancel',e=>{e.preventDefault();closeSheet(d);});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet(d);}});}
$('#install').onclick=()=>info('Добавить на главный экран','<p class="info-copy">На iPhone: откройте сайт в Safari → «Поделиться» → «На экран Домой». На Android: меню Chrome → «Добавить на главный экран» или «Установить приложение», если браузер предлагает этот пункт.</p><p class="note">Интерфейс работает онлайн. Push-уведомления и работа без интернета в этой версии не подключены.</p>');
$('#owner-open').onclick=()=>navigate('owner');
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)||'home',false));
window.addEventListener('storage',()=>{if(demo&&view==='owner')loadOwner();if(view==='bookings')renderBookings();});
function serviceCard(s){const i=config.services.indexOf(s);return `<article class="service reveal" style="--card-index:${i}"><div class="service-top"><span class="service-symbol">${icons[s.id]||icons.sparkle}</span><span class="service-index">0${i+1}</span></div><div class="service-labels"><span class="tag">${esc(s.tag)}</span><span class="duration">${icons.clock} ${duration(s.duration)}</span></div><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="service-bottom"><div><span class="price-label">Стоимость</span><strong>${money(s.price)}</strong></div><button class="round-arrow" data-book="${esc(s.id)}" aria-label="Записаться: ${esc(s.name)}">${icons.arrow}</button></div></article>`;}
function bindBooks(){document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking(b.dataset.book||config.services[0].id));}
function renderHome(){
 $('#view').innerHTML=`<section class="hero-grid"><div class="hero-image"><img src="assets/studio-hero-v2.png" width="1536" height="1024" alt="Графитовый спортивный автомобиль в студии с кольцевым светом — визуализация" fetchpriority="high"><div class="image-topline"><span class="image-label">${esc(config.name)} / DETAILING</span><span class="image-cross" aria-hidden="true">+</span></div><div class="image-bottomline"><span>Точность в каждой детали</span><span>01 — 04</span></div><div class="image-glow" aria-hidden="true"></div></div><div class="hero-copy"><span class="pill"><i></i>${esc(config.location)}</span><div class="hero-eyebrow"><span></span>ЭСТЕТИКА. ЗАЩИТА. ХАРАКТЕР.</div><h1>Ваш автомобиль.<br><em>Новый уровень.</em></h1><p>${esc(config.description)}</p><button class="primary" data-book="">Выбрать услугу и время ${icons.arrow}</button><div class="hero-footnote">${icons.check} Без звонков и регистрации</div></div></section><section class="stats reveal" aria-label="О студии"><div class="stat"><span class="stat-icon">${icons.sparkle}</span><div><strong>${config.services.length} услуги</strong><small>от мойки до защиты кузова</small></div></div><div class="stat"><span class="stat-icon">${icons.garage}</span><div><strong>${config.resources} бокса</strong><small>время только для вашего авто</small></div></div><div class="stat"><span class="stat-icon">${icons.tag}</span><div><strong>от ${money(Math.min(...config.services.map(s=>s.price)))}</strong><small>прозрачный прайс до записи</small></div></div></section><section class="service-section"><div class="section-heading reveal"><div><span class="eyebrow"><b>01 /</b> МЕНЮ УХОДА</span><h2>Детали решают <em>всё.</em></h2></div><button class="text-link" id="all-services">Выбрать услугу ${icons.arrow}</button></div><div class="services-grid">${config.services.map(serviceCard).join('')}</div></section><section class="how-section reveal"><div class="section-heading"><div><span class="eyebrow"><b>02 /</b> ВСЁ ПРОСТО</span><h2>От записи <em>до блеска.</em></h2></div><p>Пара минут — и забота<br>об автомобиле в вашем расписании.</p></div><div class="how-grid"><article><span class="how-number">01</span><h3>Выберите уход</h3><p>Услуга, стоимость и длительность — всё перед вами.</p></article><article><span class="how-number">02</span><h3>Найдите своё время</h3><p>Покажем свободные окна с учётом графика студии.</p></article><article><span class="how-number">03</span><h3>Приезжайте в студию</h3><p>Оставьте контакты и дождитесь подтверждения мастера.</p></article></div></section><section class="process reveal"><div class="process-orbit" aria-hidden="true"></div><div><span class="eyebrow">ВАШ СЛЕДУЮЩИЙ ВИЗИТ</span><h2>Пусть автомобиль<br><em>снова восхищает.</em></h2><p>Выберите удобное время. О деталях позаботимся мы.</p></div><button class="primary" data-book="">Записаться в студию ${icons.arrow}</button></section>`;
 $('#all-services').onclick=()=>navigate('services');bindBooks();animateView();
}
function renderServices(){$('#view').innerHTML=`<div class="section-heading page-heading"><div><span class="eyebrow">МЕНЮ УХОДА</span><h2>Услуги <em>студии.</em></h2></div><span class="note">Цена за услугу</span></div><p class="page-intro">Выберите услугу — покажем только время, которого хватит на всю работу.</p><div class="services-grid">${config.services.map(serviceCard).join('')}</div><p class="note section-note">Время указано по Москве. В этой версии доступны работы в пределах одного рабочего дня.</p>`;bindBooks();animateView();}
function navigate(next,updateHash=true){if(!['home','services','bookings','owner'].includes(next))next='home';view=next;if(updateHash&&location.hash!=='#'+next)history.replaceState(null,'','#'+next);clearInterval(pollTimer);document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===next);if(b.dataset.view===next)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});updateNavigation(next);window.scrollTo({top:0,behavior:'instant'});if(next==='home')renderHome();if(next==='services')renderServices();if(next==='bookings')renderBookings();if(next==='owner'){loadOwner();pollTimer=setInterval(()=>{if(view==='owner'&&ownerTab==='appointments'&&!document.hidden&&!$('#booking-dialog').open)loadOwner(true);},15000);}}
function openBooking(id){booking={serviceId:id,date:dateKey(new Date(Date.now()+864e5)),time:'',name:'',phone:'',car:'',consent:false,requestKey:crypto.randomUUID(),token:crypto.randomUUID()+crypto.randomUUID()};step=0;renderStep();$('#booking-dialog').showModal();}
function renderStep(){
 const s=config.services.find(s=>s.id===booking.serviceId), host=$('#booking-content');
 updateProgress(step);animateStep(host);
 if(step===0){host.innerHTML=`<span class="note">ШАГ 1 ИЗ 3</span><h2>Какой уход нужен?</h2><label>Услуга<select id="service-select">${config.services.map(s=>`<option value="${esc(s.id)}" ${s.id===booking.serviceId?'selected':''}>${esc(s.name)} · ${money(s.price)}</option>`).join('')}</select></label><div class="summary"><strong>${esc(s.name)}</strong><br><span>${esc(s.description)}</span><br>${duration(s.duration)} · ${money(s.price)}</div><button class="primary full" id="step-next">Выбрать время <span>→</span></button>`;$('#service-select').onchange=e=>{booking.serviceId=e.target.value;booking.time='';renderStep();};$('#step-next').onclick=()=>{step=1;renderStep();};}
 if(step===1){host.innerHTML=`<button class="back" id="step-back">← К услуге</button><h2>Когда вам удобно?</h2><p class="note">${esc(s.name)} · ${duration(s.duration)} · Москва (UTC+3)</p><div class="dates">${Array.from({length:7},(_,i)=>{const d=dateKey(new Date(Date.now()+i*864e5));return `<button class="date-btn ${d===booking.date?'selected':''}" data-date="${d}">${new Date(d+'T12:00:00+03:00').toLocaleDateString('ru',{weekday:'short'})}<strong>${Number(d.slice(8))}</strong>${new Date(d+'T12:00:00+03:00').toLocaleDateString('ru',{month:'short'})}</button>`;}).join('')}</div><label>Другая дата<input type="date" id="date-select" min="${dateKey()}" max="${dateKey(new Date(Date.now()+60*864e5))}" value="${booking.date}"></label><div id="slot-list" class="slots"></div><div id="slot-error" class="error" role="alert"></div><button class="primary full" id="step-next" disabled>Продолжить <span>→</span></button>`;
 $('#step-back').onclick=()=>{step=0;renderStep();};document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{booking.date=b.dataset.date;booking.time='';renderStep();});$('#date-select').onchange=e=>{if(e.target.value){booking.date=e.target.value;booking.time='';renderStep();}};$('#step-next').onclick=()=>{step=2;renderStep();};loadSlots();}
 if(step===2){host.innerHTML=`<button class="back" id="step-back">← Ко времени</button><h2>Осталось познакомиться</h2><div class="summary"><strong>${esc(s.name)}</strong><br><span>${niceDate(booking.date)}, ${booking.time}–${clock(Number(booking.time.slice(0,2))*60+Number(booking.time.slice(3))+s.duration)}</span><br>${money(s.price)}</div>${demo?'<div class="demo-warning">Тестовая заявка сохранится только в этом браузере. Используйте вымышленные данные.</div>':''}<form id="contact-form"><label>Ваше имя<input name="name" autocomplete="name" minlength="2" maxlength="80" value="${esc(booking.name)}" required placeholder="Как к вам обращаться"></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" maxlength="24" pattern="[+0-9 ()-]{10,24}" value="${esc(booking.phone)}" required placeholder="+7 999 123-45-67"></label><label>Автомобиль <span class="note">· необязательно</span><input name="car" maxlength="100" value="${esc(booking.car)}" placeholder="Марка и модель"></label><label class="check-label"><input name="consent" type="checkbox" required ${booking.consent?'checked':''}>Согласен с <a href="#" id="privacy">условиями обработки данных</a></label><div id="submit-error" class="error" role="alert"></div><button class="primary full" type="submit">${demo?'Отправить тестовую заявку':'Отправить заявку'} <span>↗</span></button><p class="note">Мастер подтвердит заявку. Время резервируется сразу после отправки.</p></form>`;
 $('#step-back').onclick=()=>{const f=$('#contact-form');booking={...booking,...Object.fromEntries(new FormData(f)),consent:f.consent.checked};step=1;renderStep();};$('#privacy').onclick=e=>{e.preventDefault();info('Обработка данных',`<p class="info-copy">${demo?'Это демонстрация: введите вымышленные имя и телефон. Данные хранятся в вашем браузере.':'Имя, телефон и автомобиль сохраняются на сервере студии для обработки заявки и связи по записи.'}</p><p class="note">Перед запуском для реальных клиентов владелец должен указать свои реквизиты, контакты, сроки хранения и утвердить политику обработки персональных данных. Этот текст — технический шаблон.</p>`);};$('#contact-form').onsubmit=submitBooking;}
}
async function loadSlots(){const generation=++slotGeneration;$('#slot-list').innerHTML='<span class="note">Загружаем окна…</span>';try{const slots=demo?available(config,demoState().schedule,demoState().bookings,booking.date,booking.serviceId):(await api(`/slots?date=${booking.date}&service=${booking.serviceId}`)).slots;if(generation!==slotGeneration||step!==1)return;$('#slot-list').innerHTML=slots.map(t=>`<button class="slot ${booking.time===t?'selected':''}" data-time="${t}">${t}</button>`).join('');if(!slots.length)$('#slot-error').textContent='На эту дату нет подходящих окон. Выберите другой день.';$('#step-next').disabled=!slots.includes(booking.time);document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{booking.time=b.dataset.time;document.querySelectorAll('[data-time]').forEach(x=>x.classList.toggle('selected',x===b));$('#step-next').disabled=false;});}catch(e){if(generation!==slotGeneration||step!==1)return;$('#slot-list').innerHTML='';$('#slot-error').textContent=e.message;}}
async function submitBooking(e){e.preventDefault();const f=e.target;booking={...booking,...Object.fromEntries(new FormData(f)),consent:f.consent.checked};const btn=f.querySelector('button[type=submit]');btn.disabled=true;$('#submit-error').textContent='';try{
 let result;if(demo){const state=demoState();if(!available(config,state.schedule,state.bookings,booking.date,booking.serviceId).includes(booking.time))throw new Error('Время уже занято. Вернитесь и выберите другое.');const s=config.services.find(s=>s.id===booking.serviceId),start=Number(booking.time.slice(0,2))*60+Number(booking.time.slice(3));const resource=Array.from({length:config.resources},(_,i)=>i+1).find(r=>!state.bookings.some(b=>b.resource===r&&b.date===booking.date&&b.status!=='cancelled'&&start<b.start+b.duration&&start+s.duration>b.start));result={...booking,id:crypto.randomUUID(),start,duration:s.duration,resource,serviceName:s.name,price:s.price,status:'pending'};state.bookings.push(result);save('graphite-demo',state);}else result=await api('/bookings','POST',booking);
 const key=demo?'graphite-demo-mine':'graphite-mine';const mine=read(key,[]);if(!mine.some(b=>b.id===result.id))mine.push({id:result.id,token:booking.token});save(key,mine);
 $('#booking-content').innerHTML=`<div class="success-mark">✓</div><span class="eyebrow">${demo?'ДЕМОНСТРАЦИЯ':'ЗАЯВКА ОТПРАВЛЕНА'}</span><h2>${demo?'Тестовая заявка создана':'Ждём вас в студии'}</h2><p>${demo?'Откройте кабинет мастера в этом же браузере — заявка уже там.':'Мастер увидит заявку в кабинете и свяжется с вами для подтверждения.'}</p><div class="summary"><strong>${esc(result.serviceName)}</strong><br>${niceDate(result.date)}, ${clock(result.start)} · ${money(result.price)}<br><span>Бокс ${result.resource} · ${statusNames[result.status]}</span></div><p class="note">Доступ к записи сохранён в этом браузере. Не очищайте его данные до визита.</p><button class="primary full" id="show-mine">Моя запись <span>→</span></button>`;$('#show-mine').onclick=()=>{$('#booking-dialog').close();navigate('bookings');};
 }catch(error){$('#submit-error').textContent=error.message;btn.disabled=false;}}
function bookingCard(b,isOwner=false){return `<article class="booking-card"><span class="status ${b.status}">${statusNames[b.status]}</span><h3>${esc(b.serviceName)}</h3><div class="booking-meta"><span>▤ ${niceDate(b.date)}</span><span>◷ ${clock(b.start)}–${clock(b.start+b.duration)}</span><span>Бокс ${b.resource}</span><span>${money(b.price)}</span></div>${isOwner?`<p>${esc(b.name)} · <a href="tel:${esc(b.phone.replace(/[^+0-9]/g,''))}">${esc(b.phone)}</a>${b.car?' · '+esc(b.car):''}</p>`:''}<div class="actions">${b.status==='pending'&&isOwner?`<button class="secondary" data-action="confirmed" data-id="${b.id}">Подтвердить</button>`:''}${['pending','confirmed'].includes(b.status)?`${isOwner?`<button class="secondary" data-action="completed" data-id="${b.id}">Выполнено</button>`:`<button class="secondary" data-ics="${b.id}">В календарь ↗</button>`}<button class="secondary" data-action="cancelled" data-id="${b.id}">Отменить</button>`:''}</div></article>`;}
async function changeStatus(id,status,isOwner){if(status==='cancelled'&&!confirm('Отменить запись и освободить время?'))return;try{if(demo){const state=demoState(),b=state.bookings.find(b=>b.id===id);b.status=status;save('graphite-demo',state);}else{const token=read('graphite-mine',[]).find(b=>b.id===id)?.token;await api('/bookings/'+id,'PATCH',{status},isOwner?undefined:token);}toast('Статус обновлён');if(isOwner)loadOwner();else renderBookings();}catch(e){toast(e.message);}}
function bindActions(isOwner,rows){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>changeStatus(b.dataset.id,b.dataset.action,isOwner));document.querySelectorAll('[data-ics]').forEach(b=>b.onclick=()=>downloadICS(rows.find(x=>x.id===b.dataset.ics)));}
async function renderBookings(){$('#view').innerHTML='<div class="section-heading"><div><span class="eyebrow">ВАШИ ПЛАНЫ</span><h2>Моя запись</h2></div><button class="text-link" id="refresh-mine">Обновить ↻</button></div><div id="mine-list" class="skeleton">Загружаем записи…</div>';$('#refresh-mine').onclick=renderBookings;try{
 const mine=read(demo?'graphite-demo-mine':'graphite-mine',[]);const results=await Promise.allSettled(mine.map(m=>demo?Promise.resolve(demoState().bookings.find(b=>b.id===m.id)):api('/bookings/'+m.id,'GET',null,m.token)));if(view!=='bookings')return;const rows=results.filter(r=>r.status==='fulfilled'&&r.value).map(r=>r.value);$('#mine-list').className='';$('#mine-list').innerHTML=(results.some(r=>r.status==='rejected')?'<p class="error">Часть записей не удалось загрузить. Повторите обновление.</p>':'')+(rows.length?rows.reverse().map(b=>bookingCard(b)).join(''):'<div class="empty"><h3>Здесь будет ваша запись</h3><p>Выберите услугу и удобное время.</p><button class="primary" data-book="">Записаться ↗</button></div>')+'<p class="note">Здесь показаны записи, созданные в этом браузере. Обновите страницу, чтобы проверить подтверждение мастера.</p>';bindActions(false,rows);bindBooks();
 }catch(e){if(view==='bookings')$('#mine-list').textContent=e.message;}}
async function loadOwner(silent=false){if(!silent)$('#view').innerHTML='<div class="skeleton">Открываем кабинет…</div>';try{ownerData=demo?demoState():await api('/owner');if(view==='owner')renderOwner();}catch(e){if(view!=='owner')return;if(e.message.includes('Войдите'))renderLogin();else if(!silent)$('#view').innerHTML=`<p class="error">${esc(e.message)}</p><button class="secondary" id="retry-owner">Повторить</button>`;if($('#retry-owner'))$('#retry-owner').onclick=()=>loadOwner();}}
function renderLogin(){$('#view').innerHTML='<form class="login-form" id="owner-login"><span class="eyebrow">КАБИНЕТ МАСТЕРА</span><h2>Добро пожаловать</h2><p>Войдите, чтобы видеть заявки и управлять графиком.</p><label>Пароль<input name="password" type="password" autocomplete="current-password" required></label><div class="error" id="login-error" role="alert"></div><button class="primary full">Войти →</button></form>';$('#owner-login').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await api('/login','POST',{password:e.target.password.value});loadOwner();}catch(err){$('#login-error').textContent=err.message;btn.disabled=false;}};}
function renderOwner(){
 $('#view').innerHTML=`<div class="section-heading owner-heading"><div><span class="eyebrow">КАБИНЕТ МАСТЕРА</span><h2>Студия под контролем</h2><p class="note">${esc(config.name)} · Москва (UTC+3)</p></div><button class="secondary" id="logout">${demo?'Клиентский вид':'Выйти'}</button></div>${demo?'<div class="demo-warning">Открытый демо-кабинет. Только тестовые заявки этого браузера. В серверной версии кабинет защищён паролем.</div>':''}<div class="owner-tabs"><button class="secondary ${ownerTab==='appointments'?'selected':''}" data-tab="appointments">Заявки</button><button class="secondary ${ownerTab==='schedule'?'selected':''}" data-tab="schedule">График работы</button></div><div id="owner-content"></div>`;
 $('#logout').onclick=async()=>{try{if(!demo)await api('/logout','POST',{});ownerData=null;navigate('home');}catch(e){toast(e.message);}};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{ownerTab=b.dataset.tab;renderOwner();});
 if(ownerTab==='appointments'){
 const rows=ownerData.bookings;$('#owner-content').innerHTML=`<div class="stats"><div class="stat"><strong>${rows.filter(b=>b.status==='pending').length}</strong><small>ждут подтверждения</small></div><div class="stat"><strong>${rows.filter(b=>b.date===dateKey()&&b.status!=='cancelled').length}</strong><small>записей на сегодня</small></div><div class="stat"><strong>${rows.filter(b=>b.status==='completed').length}</strong><small>работ выполнено</small></div></div><label>Показать<select id="filter"><option value="active">Предстоящие и ожидающие</option><option value="today">Сегодня</option><option value="all">Все записи</option><option value="cancelled">Отменённые</option></select></label><div id="owner-list"></div><p class="note">${demo?'Изменения видны в этом браузере.':'Список обновляется каждые 15 секунд. Для срочной проверки нажмите «Обновить».'}</p><button class="secondary" id="owner-refresh">Обновить ↻</button>`;
 const refresh=()=>{const f=$('#filter').value,selected=rows.filter(b=>f==='all'||(f==='today'&&b.date===dateKey())||(f==='cancelled'&&b.status==='cancelled')||(f==='active'&&['pending','confirmed'].includes(b.status)&&b.date>=dateKey()));$('#owner-list').innerHTML=selected.length?selected.map(b=>bookingCard(b,true)).join(''):'<div class="empty"><h3>Записей пока нет</h3><p>Здесь появятся заявки клиентов.</p></div>';bindActions(true,rows);};$('#filter').onchange=refresh;$('#owner-refresh').onclick=()=>loadOwner();refresh();
 }else renderSchedule();
}
function renderSchedule(){const s=ownerData.schedule,days=['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'];$('#owner-content').innerHTML=`<h3>Обычная рабочая неделя</h3><p class="note">Укажите часы приёма. Услуга должна полностью помещаться в рабочий день. Текущие записи при изменении графика сохранятся.</p><form id="schedule-form">${[1,2,3,4,5,6,0].map(i=>`<div class="week-row"><label><input type="checkbox" name="open-${i}" ${s.week[i].open?'checked':''}>${days[i]}</label><input type="time" name="start-${i}" step="1800" value="${s.week[i].start}" required aria-label="${days[i]}: начало"><input type="time" name="end-${i}" step="1800" value="${s.week[i].end}" required aria-label="${days[i]}: конец"></div>`).join('')}<h3>Выходной в отдельную дату</h3><label>Дата<input type="date" id="exception-date" min="${dateKey()}" max="${dateKey(new Date(Date.now()+60*864e5))}"></label><button class="secondary full" type="button" id="add-day-off">Добавить выходной</button><div id="exceptions"></div><div class="error" id="schedule-error" role="alert"></div><button class="primary full" type="submit">Сохранить график <span>✓</span></button></form>`;
 const exceptions=structuredClone(s.exceptions);function showExceptions(){$('#exceptions').innerHTML=Object.keys(exceptions).sort().map(d=>`<div class="booking-meta"><span>${niceDate(d)} · выходной</span><button type="button" class="text-link" data-remove="${d}">Убрать</button></div>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{delete exceptions[b.dataset.remove];showExceptions();});}showExceptions();$('#add-day-off').onclick=()=>{const date=$('#exception-date').value;if(!date)return toast('Сначала выберите дату');exceptions[date]={open:false,start:'09:00',end:'20:00'};showExceptions();};$('#schedule-form').onsubmit=async e=>{e.preventDefault();const form=e.target,next={week:s.week.map((_,i)=>({open:form.elements['open-'+i].checked,start:form.elements['start-'+i].value,end:form.elements['end-'+i].value})),exceptions};if(!validateSchedule(next)){$('#schedule-error').textContent='Проверьте часы: шаг 30 минут, конец позже начала.';return;}try{if(demo){const state=demoState();state.schedule=next;save('graphite-demo',state);}else await api('/schedule','PUT',next);ownerData.schedule=next;toast('График сохранён');}catch(err){$('#schedule-error').textContent=err.message;}};}
function downloadICS(b){const fmt=(date,start)=>new Date(Date.parse(date+'T'+clock(start)+config.offset)).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';const safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,' ');const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Graphite//Booking//RU','BEGIN:VEVENT','UID:'+b.id+'@graphite-booking','DTSTAMP:'+fmt(dateKey(),720),'DTSTART:'+fmt(b.date,b.start),'DTEND:'+fmt(b.date,b.start+b.duration),'SUMMARY:'+safe(b.serviceName+' — '+config.name),'DESCRIPTION:'+safe('Заявка: '+statusNames[b.status]+'. Проверьте подтверждение мастера.'),'END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='booking.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function init(){try{const response=await fetch(new URL('api/config',import.meta.url));if(response.ok&&response.headers.get('content-type')?.includes('application/json')){config=await response.json();if(config.mode!=='server')throw new Error('Неизвестный режим сервера');}else if(response.status===404||response.ok){const r=await fetch('business.json');if(!r.ok)throw new Error('Не удалось загрузить настройки');config=await r.json();demo=true;}else throw new Error('Сервер недоступен. Повторите позже.');$('#brand').textContent=config.name;$('#footer-brand').textContent=config.name;document.title=config.name+' — онлайн-запись';$('#mode').textContent=demo?'Демонстрация · тестовые данные только в этом браузере':'Онлайн-запись · заявки поступают мастеру';navigate(location.hash.slice(1)||'home',false);}catch(e){$('#view').innerHTML=`<div class="empty"><h3>Не удалось открыть студию</h3><p>${esc(e.message)}</p><button class="secondary" onclick="location.reload()">Повторить</button></div>`;}}
setupMotion();init();
